const catalog = [...HELP_TOPICS, ...DANCER_ONBOARDING_HELP_TOPICS, ...CLUB_APPROVAL_HELP_TOPICS, ...SECTION_HELP_TOPICS];
const contact = HELP_TOPICS.find(topic => topic.id === "human")!;
const staffInboxHelp: Topic = { ...contact, title: "Use the support inbox", phrases: ["messages", "support inbox", "reply to accounts"], answer: "Open Messages to see account conversations. Select a conversation to read it and reply.", roles: ["admin", "support"] };
const staffEmailHelp: Topic = { ...contact, answer: "Open Messages and enter your question. Choose Open email and send the draft from your email app. The team will reply by email.", roles: ["reviewer", "billing", "compliance"] };

export function helpTopicsFor(role: HelpRole, context: HelpContext = "dashboard") {
  const handoff = staffInboxHelp.roles.includes(role) ? staffInboxHelp : staffEmailHelp.roles.includes(role) ? staffEmailHelp : contact;
  if (role === "venue" && context === "venue-approval") return CLUB_APPROVAL_HELP_TOPICS;
  if (role === "dancer" && context === "dancer-onboarding") return [...DANCER_ONBOARDING_HELP_TOPICS, handoff];
  if (context === "dashboard") return [...HELP_TOPICS.filter(topic => topic.id !== "human" && topic.roles.includes(role)), handoff];
  const section = helpSection(context);
  if (!section || !sectionAllowsRole(context, role)) return [handoff];
  return [...section.topics.flatMap(id => catalog.filter(topic => topic.id === id && topic.roles.includes(role))), handoff];
}

function sectionAllowsRole(context: HelpContext, role: HelpRole) {
  if (context.startsWith("customer-")) return role === "customer";
  if (context.startsWith("vip-")) return role === "vip";
  if (context.startsWith("dancer-") || context.startsWith("setup-")) return role === "dancer";
  if (context.startsWith("venue-")) return clubs.some(clubRole => clubRole === role);
  if (context.startsWith("admin-")) {
    if (context === "admin-account") return admins.some(adminRole => adminRole === role);
    if (context === "admin-support-staff") return role === "support";
    return role === "admin" || (role === "reviewer" && context === "admin-media")
      || (role === "billing" && context === "admin-money") || (role === "compliance" && context === "admin-compliance");
  }
  return context === "account-paused" || context === "support-only";
}
const normalize = (text: string) => text.toLowerCase().normalize("NFKD").replace(/[’']/g, "").replace(/[^a-z0-9]+/g, " ").trim();
const stopWords = new Set("a an the i my me we our you your how what where when why can do does is are to for of on in it this that and or with from at as be please help want need get about have has am not cant dont im here find see use using which would could should will lets some again".split(" "));
const singular: Record<string, string> = { photos: "photo", pictures: "picture", videos: "video", dancers: "dancer", clubs: "club", requests: "request", alerts: "alert", notifications: "notification", accounts: "account", shifts: "shift", guests: "guest", tables: "table", uploads: "upload", approved: "approve", approving: "approve", rejected: "reject", reviewing: "review", uploading: "upload", sending: "send" };
const words = (text: string) => new Set(normalize(text).split(" ").filter(word => word && !stopWords.has(word)).map(word => Object.hasOwn(singular, word) ? singular[word] : word));
export type HelpMatch = { kind: "answer"; topic: Topic } | { kind: "suggestions"; topics: Topic[] } | { kind: "unknown" };

// Deliberately bounded retrieval: no generated answers, network requests, or live account access.
export function matchHelpQuestion(role: HelpRole, question: string, context: HelpContext = "dashboard"): HelpMatch {
  const query = normalize(question).slice(0, 600);
  if (!query) return { kind: "unknown" };
  // Individual decisions and sensitive data need a human, even if a feature keyword matches.
  if (/\b(refund|charged twice|stolen|hacked|emergency|harassment|abuse|lawsuit)\b/.test(query)
    || /\bwhy\b.*\b(rejected|declined|suspended|banned|charged)\b/.test(query)
    || /\b(show|give|tell|reveal)\b.*\b(password|token|secret|someone elses|another users)\b/.test(query)) return { kind: "unknown" };
  const queryWords = words(query);
  const allowed = helpTopicsFor(role, context);
  const exact = allowed.find(topic => normalize(topic.title) === query);
  if (exact) return { kind: "answer", topic: exact };
  const score = (topic: Topic) => {
    const keywords = words([topic.title, ...topic.phrases].join(" "));
    const hits = [...queryWords].filter(word => keywords.has(word)).length;
    const phrases = topic.phrases.filter(phrase => (` ${query} `).includes(` ${normalize(phrase)} `));
    const longest = Math.max(0, ...phrases.map(phrase => words(phrase).size));
    return { topic, keywords, score: hits + longest * 3, hits, coverage: hits / Math.max(1, queryWords.size), longest };
  };
  const scored = allowed.map(score).filter(item => item.hits > 0 && item.coverage >= .5)
    .sort((a, b) => b.score - a.score);
  const best = scored[0];
  if (!best) return { kind: "unknown" };
  // A more specific question about another screen must not become a generic
  // answer here just because the two screens share a word like “requests”.
  const allowedIds = new Set(allowed.map(topic => topic.id));
  if (catalog.some(topic => {
    if (allowedIds.has(topic.id)) return false;
    if (normalize(topic.title) === query) return true;
    const other = score(topic);
    return best.coverage < 1 && other.hits > best.hits && other.score >= best.score;
  })) return { kind: "unknown" };
  const alternatives = scored.filter(item => item.longest > 0 && best.score - item.score < 3).slice(0, 3);
  if (alternatives.length > 1 && [...queryWords].every(word => alternatives.some(item => item.keywords.has(word)))) {
    return { kind: "suggestions", topics: alternatives.map(item => item.topic) };
  }
  if (best.coverage < 1) return { kind: "unknown" };
  return { kind: "answer", topic: best.topic };
}

export function helpSupportRole(role: HelpRole) {
  if (role === "customer" || role === "vip") return "customer";
  if (role === "venue" || role === "manager" || role === "staff") return "venue";
  return role === "dancer" ? "dancer" : null;
}
export function helpSupportHref(role: HelpRole) {
  const accountRole = helpSupportRole(role);
  return accountRole ? `/dashboard/${accountRole}?help=support#${accountRole}-support` : null;
}
export function helpEmailHref(role: HelpRole, message: string) {
  return `mailto:${OPERATIONS_SUPPORT_EMAIL}?subject=${encodeURIComponent(`${HELP_ROLE_LABELS[role]} dashboard help`)}&body=${encodeURIComponent(message.slice(0, 4000))}`;
}
